-- Création de la table piscine
CREATE TABLE piscine (
    id INT PRIMARY KEY AUTO_INCREMENT,
    type_piscine VARCHAR(255),
    nom VARCHAR(255),
    arrondissement VARCHAR(255),
    adresse VARCHAR(255),
    gestion VARCHAR(255),
    equipement VARCHAR(255),
    longitude DECIMAL(10,7),
    latitude DECIMAL(10,7)
);

